from solution import display_width
import unicodedata


def test_basic():
    assert display_width('abc') == 3
    assert display_width('') == 0
    assert display_width('한국') == 4


def test_combining():
    assert display_width('e\u0301') == 1


def test_zwj():
    assert display_width('\u200d') == 0
    assert display_width('a\u200db') == 2


def test_emoji_zwj():
    assert display_width('👨\u200d👩') == 4


def test_fullwidth():
    assert display_width('Ａ') == 2


def test_wide_combining_marks():
    for ch in ['\u3099', '\u309a', '\u302a', '\u302b', '\u302c', '\u302d']:
        if unicodedata.category(ch) in ('Mn', 'Me'):
            assert display_width(ch) == 0
            assert display_width('あ' + ch) == 2


def test_wide_format_chars():
    for cp in range(0x110000):
        ch = chr(cp)
        if unicodedata.category(ch) == 'Cf' and unicodedata.east_asian_width(ch) in ('W', 'F'):
            assert display_width(ch) == 0


def test_control_and_misc():
    assert display_width('\t') == 1
    assert display_width(' ') == 1
    assert display_width('日本語') == 6

from solution import display_width


